    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int ans = 0, i = 0, n = 0, top = 0;
    // 完整输入用 - 表示空串；核心函数直接接收真实字符串。
    n = readstr(a);
    top = 0;
    // 栈底保存开始之前的边界 -1，其他项保存未匹配左括号下标。
    b[0] = (-1);
    ans = 0;
    for (i = 0; i < n; i += 1)  {
        if (a[i] == 40)  {
            top = (top + 1);
            b[top] = i;
        }
        else  {
            top = (top - 1);
            // 没有左括号可配对时，当前右括号成为不能跨过的新边界。
            if (top < 0)  {
                top = 0;
                b[0] = i;
            }
            else  {
                ans = mx(ans, (i - b[top]));
            }
        }
    }
    // 答案是所有右括号结尾的有效连续后缀长度的最大值。
    emit(ans);
    return 0;
}

